const showDiagram=document.createElement('button');showDiagram.className='tidal-diagram-button';showDiagram.textContent='▤　查看系统结构线图';showDiagram.setAttribute('aria-expanded','false');
showDiagram.onclick=()=>{diagram.open=!diagram.open;showDiagram.setAttribute('aria-expanded',String(diagram.open));if(diagram.open)diagram.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'nearest'});};
