const summaries={aero:'叶片来流与机组运动共同影响气动力，载荷传递至转子与塔架。',hydro:'波浪作用与平台运动相互影响，结构与系泊共同参与耦合求解。',structure:'各类载荷共同影响结构运动，结合转速、平台响应与塔底弯矩观察。',mooring:'系泊线连接平台与海床，平台运动与系泊恢复作用双向耦合。',control:'机组状态与控制动作共同参与耦合计算。比较前统一分析窗口。'};
function sync(){const id=page.dataset.topic||'hydro';document.getElementById('atlas-reading-text').textContent=summaries[id];module.querySelector('.kicker').textContent=labels[id];module.querySelector('.tidal-component-label').textContent=components[id];}
new MutationObserver(sync).observe(page,{attributes:true,attributeFilter:['data-topic']});sync();
